dashboard.definition:
{
    "title": "OR Management",
    "description": "OR Management: daily schedule of all ORs, status, utilization and cancelled cases",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Department",
            "options": {
                "items": [
                    {
                        "label": "All departments",
                        "value": "*"
                    },
                    {
                        "label": "Internal Medicine (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Cardiology (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurology (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Oncology (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "General Surgery (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Trauma Surgery/Orthopedics (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urology (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anesthesia/OR (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensive Care (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Emergency Department (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiology (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynecology/Obstetrics (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Pediatrics (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatry (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        },
        "input_room": {
            "type": "input.dropdown",
            "title": "OR room",
            "dataSources": {
                "primary": "ds_room_list"
            },
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "room",
                "defaultValue": "*"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All rooms"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"room\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"room\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "room": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_room_list": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:or:case\" earliest=@d latest=+1d | stats count by room | eval n=tonumber(replace(room, \"[^0-9]\", \"\")) + if(like(room, \"OP-D%\"), 100, 0) | sort n | fields room",
                "enableSmartSources": true
            },
            "name": "ORs"
        },
        "ds_today": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:or:case\" (type=plan OR type=milestone) earliest=@d latest=+1d department=\"$dept$\"\n| stats latest(planned_start) as planned_start latest(planned_end) as planned_end min(actual_start) as actual_start max(actual_end) as actual_end latest(status) as status latest(procedure) as procedure latest(department) as department latest(delay_min) as delay_min by room case_id",
                "enableSmartSources": true
            },
            "name": "OR cases today"
        },
        "ds_k_cases": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| stats count as \"Cases today\""
            }
        },
        "ds_k_done": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| where isnotnull(actual_end) | stats count as Completed"
            }
        },
        "ds_k_cancel": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| where like(status, \"cancelled%\") | stats count as Cancelled"
            }
        },
        "ds_k_delay": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| where isnotnull(actual_start) | eval d=(actual_start - planned_start) / 60 | stats avg(d) as \"Delay (min)\" | eval \"Delay (min)\"=round('Delay (min)', 0)"
            }
        },
        "ds_rooms": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:or:case\" type=room_status earliest=-10m\n| stats latest(phase) as phase latest(procedure) as procedure latest(department) as department latest(delay_min) as delay_min latest(cases_done) as done latest(cases_today) as total latest(cases_cancelled) as cancelled latest(utilization_pct) as util by room suite",
                "enableSmartSources": true
            },
            "name": "Room status"
        },
        "ds_k_running": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rooms",
                "query": "| where phase=\"Surgery in progress\" OR phase=\"Induction\" OR phase=\"Emergence\" | stats count as \"Rooms in use\""
            }
        },
        "ds_k_util": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rooms",
                "query": "| stats avg(util) as Utilization | eval Utilization=round(Utilization, 1)"
            }
        },
        "ds_room_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rooms",
                "query": "| eval Cases=done.\" / \".total, Phase=phase\n| table room suite Phase procedure department delay_min Cases cancelled util\n| rename room as Room suite as Area procedure as Procedure department as Department delay_min as \"Delay (min)\" cancelled as Cancelled util as \"Utilization %\""
            }
        },
        "ds_util": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_rooms",
                "query": "| table room util | rename room as Room util as \"Utilization %\""
            }
        },
        "ds_cancelled": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:or:case\" type=plan status=\"cancelled*\" earliest=@d latest=+1d\n| stats latest(procedure) as Procedure latest(department) as Department latest(planned_start) as ps latest(blood_units_planned) as EK by room case_id\n| eval Scheduled=strftime(ps, \"%H:%M\") | table room case_id Procedure Department Scheduled EK | rename room as Room case_id as Fall EK as \"RBC planned\"",
                "enableSmartSources": true
            }
        },
        "ds_by_dept": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_today",
                "query": "| stats count as Cases by department | sort - Cases | rename department as Department"
            }
        },
        "ds_cases_room": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:or:case\" (type=plan OR type=milestone) earliest=@d latest=+1d department=\"$dept$\"\n| stats latest(planned_start) as planned_start latest(planned_end) as planned_end min(actual_start) as actual_start max(actual_end) as actual_end latest(status) as status latest(procedure) as procedure latest(department) as department latest(delay_min) as delay_min by room case_id | search room=\"$room$\"\n| eval Scheduled=strftime(planned_start, \"%H:%M\").\"–\".strftime(planned_end, \"%H:%M\"), Start=strftime(actual_start, \"%H:%M\"), End=strftime(actual_end, \"%H:%M\")\n| sort planned_start | table room case_id procedure department Scheduled Start End status\n| rename room as Room case_id as Fall procedure as Procedure department as Department status as Status",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
