        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_delay"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 15,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 15,
                        "to": 30,
                        "value": "#c98a00"
                    },
                    {
                        "from": 30,
                        "value": "#c8253f"
                    }
                ]
            }
