                "primary": "ds_k_util"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#0b7fab",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 40,
                        "value": "#c8253f"
                    },
                    {
                        "from": 40,
                        "to": 60,
                        "value": "#c98a00"
