        "viz_08": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_cases_room"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 9,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#e9eef4",
                    "rowColors": "#13294b",
                    "headerColor": "#5b6878"
                },
                "columnFormat": {
                    "Status": {
